use std::fmt::Write as _;

use super::*;
use super::type_helpers::*;

pub(super) fn emit_jni_cpp(spec: &HybridFileSpec, hpp_header: &str) -> String {
    let mut out = String::with_capacity(16 * 1024);
    writeln!(
        out,
        "// @generated by nve-codegen (hybrid Android C++20 JNI glue) — DO NOT EDIT."
    )
    .unwrap();
    writeln!(
        out,
        "// Binary direct JNI bindings over primitives & DirectByteBuffer -> NveHybrid*VTable."
    )
    .unwrap();
    writeln!(out, "#include <jni.h>").unwrap();
    writeln!(out, "#include <cstdint>").unwrap();
    writeln!(out, "#include <cstring>").unwrap();
    writeln!(out, "#include <span>").unwrap();
    writeln!(out, "#include <string>").unwrap();
    writeln!(out, "#include <vector>").unwrap();
    writeln!(out, "#include \"{hpp_header}\"").unwrap();
    writeln!(out).unwrap();

    writeln!(
        out,
        r#"namespace {{

void throw_java_exception(JNIEnv* env, const char* msg) {{
  jclass cls = env->FindClass("java/lang/IllegalStateException");
  if (cls) {{
    env->ThrowNew(cls, msg ? msg : "NVE hybrid call failed");
  }}
}}

std::span<const uint8_t> direct_buffer_span(JNIEnv* env, jobject buf) {{
  if (!buf) return {{}};
  auto* ptr = static_cast<const uint8_t*>(env->GetDirectBufferAddress(buf));
  const jlong cap = env->GetDirectBufferCapacity(buf);
  if (!ptr || cap <= 0) return {{}};
  return {{ptr, static_cast<size_t>(cap)}};
}}

jbyteArray to_jbyte_array(JNIEnv* env, std::span<const uint8_t> data) {{
  jbyteArray arr = env->NewByteArray(static_cast<jsize>(data.size()));
  if (arr && !data.empty()) {{
    env->SetByteArrayRegion(arr, 0, static_cast<jsize>(data.size()),
                            reinterpret_cast<const jbyte*>(data.data()));
  }}
  return arr;
}}

}} // namespace
"#
    )
    .unwrap();

    for m in &spec.modules {
        emit_jni_cpp_target(&mut out, &m.name, &m.methods, false);
    }
    for v in &spec.views {
        emit_jni_cpp_target(&mut out, &v.name, &v.methods, true);
    }
    out
}

pub(super) fn emit_jni_cpp_target(
    out: &mut String,
    name: &str,
    methods: &[HybridMethodSpec],
    is_view: bool,
) {
    let pascal = to_pascal_case(name);
    let upper = to_snake_case(name).to_ascii_uppercase();
    let cls_jni = format!("{JNI_PACKAGE_PREFIX}_{pascal}HybridClient");

    writeln!(out, "extern \"C\" {{").unwrap();
    writeln!(out).unwrap();

    // nativeCreate
    writeln!(out, "JNIEXPORT jlong JNICALL {cls_jni}_nativeCreate(JNIEnv* env, jclass) {{").unwrap();
    writeln!(out, "  try {{").unwrap();
    writeln!(
        out,
        "    const auto* vt = static_cast<const NveHybrid{pascal}VTable*>(nve_get_interface(NVE_HYBRID_{upper}_INTERFACE_ID));"
    )
    .unwrap();
    writeln!(out, "    auto* client = new nve::hybrid::{pascal}Client(vt);").unwrap();
    writeln!(out, "    return reinterpret_cast<jlong>(client);").unwrap();
    writeln!(out, "  }} catch (const std::exception& e) {{").unwrap();
    writeln!(out, "    throw_java_exception(env, e.what());").unwrap();
    writeln!(out, "    return 0;").unwrap();
    writeln!(out, "  }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    // nativeDestroy
    writeln!(
        out,
        "JNIEXPORT void JNICALL {cls_jni}_nativeDestroy(JNIEnv*, jclass, jlong handle) {{"
    )
    .unwrap();
    writeln!(out, "  delete reinterpret_cast<nve::hybrid::{pascal}Client*>(handle);").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    if is_view {
        writeln!(
            out,
            "JNIEXPORT void JNICALL {cls_jni}_nativeSetProps(JNIEnv* env, jclass, jlong handle, jobject props_buf) {{"
        )
        .unwrap();
        writeln!(out, "  auto* client = reinterpret_cast<nve::hybrid::{pascal}Client*>(handle);").unwrap();
        writeln!(out, "  if (!client) {{ throw_java_exception(env, \"null hybrid handle\"); return; }}").unwrap();
        writeln!(out, "  try {{").unwrap();
        writeln!(out, "    const auto span = direct_buffer_span(env, props_buf);").unwrap();
        writeln!(out, "    nve::hybrid::BinReader r(span);").unwrap();
        writeln!(out, "    const uint32_t count = r.begin_map();").unwrap();
        writeln!(out, "    std::vector<std::string> keys;").unwrap();
        writeln!(out, "    std::vector<std::vector<uint8_t>> raw_vals;").unwrap();
        writeln!(out, "    std::vector<NveMapEntry> entries;").unwrap();
        writeln!(out, "    keys.reserve(count); raw_vals.reserve(count); entries.reserve(count);").unwrap();
        writeln!(out, "    for (uint32_t i = 0; i < count; ++i) {{").unwrap();
        writeln!(out, "      keys.emplace_back(r.read_map_key());").unwrap();
        writeln!(out, "      const uint8_t tag = r.peek_tag();").unwrap();
        writeln!(out, "      NveMapEntry entry{{}};").unwrap();
        writeln!(out, "      entry.key = NveStrSlice{{reinterpret_cast<const uint8_t*>(keys.back().data()), keys.back().size()}};").unwrap();
        writeln!(out, "      if (tag == NVE_VAL_BOOL) {{ entry.value.tag = NVE_VAL_BOOL; entry.value.data.bool_val = r.read_bool() ? 1u : 0u; }}").unwrap();
        writeln!(out, "      else if (tag == NVE_VAL_I64) {{ entry.value.tag = NVE_VAL_I64; entry.value.data.i64_val = r.read_i64(); }}").unwrap();
        writeln!(out, "      else if (tag == NVE_VAL_F64) {{ entry.value.tag = NVE_VAL_F64; entry.value.data.f64_val = r.read_f64(); }}").unwrap();
        writeln!(out, "      else if (tag == NVE_VAL_STR) {{ auto s = r.read_str(); raw_vals.emplace_back(s.begin(), s.end()); entry.value.tag = NVE_VAL_STR; entry.value.data.str_val = NveStrSlice{{raw_vals.back().data(), raw_vals.back().size()}}; }}").unwrap();
        writeln!(out, "      else if (tag == NVE_VAL_BYTES) {{ raw_vals.push_back(r.read_bytes()); entry.value.tag = NVE_VAL_BYTES; entry.value.data.bytes_val = NveBufferSlice{{raw_vals.back().data(), raw_vals.back().size()}}; }}").unwrap();
        writeln!(out, "      else {{ raw_vals.push_back(r.read_raw_value()); entry.value.tag = NVE_VAL_BYTES; entry.value.data.bytes_val = NveBufferSlice{{raw_vals.back().data(), raw_vals.back().size()}}; }}").unwrap();
        writeln!(out, "      entries.push_back(entry);").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out, "    const int32_t st = client->vtable()->set_props_direct(client->handle(), entries.data(), static_cast<uint32_t>(entries.size()));").unwrap();
        writeln!(out, "    if (st != NVE_HYBRID_OK) {{ throw_java_exception(env, \"setProps failed\"); }}").unwrap();
        writeln!(out, "  }} catch (const std::exception& e) {{").unwrap();
        writeln!(out, "    throw_java_exception(env, e.what());").unwrap();
        writeln!(out, "  }}").unwrap();
        writeln!(out, "}}").unwrap();
        writeln!(out).unwrap();
    }

    for m in methods {
        let jni_fn = format!("{cls_jni}_native{}", to_pascal_case(&m.name));
        let cpp_mname = cpp_ident(&to_camel_case(&m.name));
        let jni_ret = jni_cpp_return_type(&m.return_type);
        write!(
            out,
            "JNIEXPORT {jni_ret} JNICALL {jni_fn}(JNIEnv* env, jclass, jlong handle"
        )
        .unwrap();
        for p in &m.params {
            let pname = cpp_ident(&p.name);
            write!(out, ", {} {pname}", jni_cpp_param_type(&p.ty)).unwrap();
        }
        writeln!(out, ") {{").unwrap();
        let zero_ret = jni_cpp_zero_return(&m.return_type);
        writeln!(out, "  auto* client = reinterpret_cast<nve::hybrid::{pascal}Client*>(handle);").unwrap();
        writeln!(out, "  if (!client) {{ throw_java_exception(env, \"null hybrid handle\"); return{zero_ret}; }}").unwrap();
        writeln!(out, "  try {{").unwrap();

        let mut call_args = Vec::new();
        for (idx, p) in m.params.iter().enumerate() {
            let pname = cpp_ident(&p.name);
            match &p.ty {
                HybridType::Bool => call_args.push(format!("{pname} != JNI_FALSE")),
                HybridType::U8 => call_args.push(format!("static_cast<uint8_t>({pname})")),
                HybridType::U16 => call_args.push(format!("static_cast<uint16_t>({pname})")),
                HybridType::Usize => call_args.push(format!("static_cast<size_t>({pname})")),
                HybridType::I32 => call_args.push(format!("static_cast<int32_t>({pname})")),
                HybridType::U32 => call_args.push(format!("static_cast<uint32_t>({pname})")),
                HybridType::I64 => call_args.push(format!("static_cast<int64_t>({pname})")),
                HybridType::U64 => call_args.push(format!("static_cast<uint64_t>({pname})")),
                HybridType::F32 => call_args.push(format!("static_cast<float>({pname})")),
                HybridType::F64 => call_args.push(format!("static_cast<double>({pname})")),
                HybridType::Enum(e) => {
                    call_args.push(format!("static_cast<nve::hybrid::{e}>(static_cast<uint32_t>({pname}))"));
                }
                HybridType::String => {
                    writeln!(out, "    const char* _cstr_{idx} = {pname} ? env->GetStringUTFChars({pname}, nullptr) : \"\";").unwrap();
                    writeln!(out, "    std::string _str_{idx}(_cstr_{idx} ? _cstr_{idx} : \"\");").unwrap();
                    writeln!(out, "    if ({pname} && _cstr_{idx}) {{ env->ReleaseStringUTFChars({pname}, _cstr_{idx}); }}").unwrap();
                    call_args.push(format!("_str_{idx}"));
                }
                HybridType::Bytes => {
                    writeln!(out, "    const auto _span_{idx} = direct_buffer_span(env, {pname});").unwrap();
                    call_args.push(format!("_span_{idx}"));
                }
                HybridType::Value => {
                    writeln!(out, "    const auto _span_{idx} = direct_buffer_span(env, {pname});").unwrap();
                    writeln!(out, "    NveValue _val_{idx}{{}}; _val_{idx}.tag = NVE_VAL_BYTES; _val_{idx}.data.bytes_val = NveBufferSlice{{_span_{idx}.data(), _span_{idx}.size()}};").unwrap();
                    call_args.push(format!("_val_{idx}"));
                }
                other => {
                    writeln!(out, "    const auto _span_{idx} = direct_buffer_span(env, {pname});").unwrap();
                    writeln!(out, "    nve::hybrid::BinReader _r_{idx}(_span_{idx});").unwrap();
                    writeln!(out, "    {} _arg_{idx}{{}};", jni_cpp_owned_type(other)).unwrap();
                    emit_jni_cpp_bin_read(out, "    ", &format!("_r_{idx}"), &format!("_arg_{idx}"), other);
                    call_args.push(format!("_arg_{idx}"));
                }
            }
        }

        let effective_ret = match &m.return_type {
            HybridType::Result { ok, .. } => ok.as_ref(),
            other => other,
        };
        let call_expr = format!("client->{cpp_mname}({})", call_args.join(", "));
        match effective_ret {
            HybridType::Void => writeln!(out, "    {call_expr};").unwrap(),
            HybridType::Bool => writeln!(out, "    return {call_expr} ? JNI_TRUE : JNI_FALSE;").unwrap(),
            HybridType::U8 | HybridType::U16 | HybridType::I32 | HybridType::U32 => {
                writeln!(out, "    return static_cast<jint>({call_expr});").unwrap()
            }
            HybridType::Usize | HybridType::I64 | HybridType::U64 => {
                writeln!(out, "    return static_cast<jlong>({call_expr});").unwrap()
            }
            HybridType::F32 => writeln!(out, "    return static_cast<jfloat>({call_expr});").unwrap(),
            HybridType::F64 => writeln!(out, "    return static_cast<jdouble>({call_expr});").unwrap(),
            HybridType::Enum(_) => writeln!(out, "    return static_cast<jint>(static_cast<uint32_t>({call_expr}));").unwrap(),
            HybridType::String => {
                writeln!(out, "    const std::string _res = {call_expr};").unwrap();
                writeln!(out, "    return env->NewStringUTF(_res.c_str());").unwrap();
            }
            HybridType::Bytes => {
                writeln!(out, "    const auto _res = {call_expr};").unwrap();
                writeln!(out, "    return to_jbyte_array(env, _res);").unwrap();
            }
            HybridType::Value => {
                writeln!(out, "    const auto _res = {call_expr};").unwrap();
                writeln!(out, "    return to_jbyte_array(env, _res.bin_bytes);").unwrap();
            }
            other => {
                writeln!(out, "    const auto _res = {call_expr};").unwrap();
                writeln!(out, "    nve::hybrid::BinWriter _rw;").unwrap();
                emit_jni_cpp_bin_write(out, "    ", "_rw", "_res", other);
                writeln!(out, "    return to_jbyte_array(env, _rw.bytes());").unwrap();
            }
        }

        writeln!(out, "  }} catch (const std::exception& e) {{").unwrap();
        writeln!(out, "    throw_java_exception(env, e.what());").unwrap();
        writeln!(out, "    return{zero_ret};").unwrap();
        writeln!(out, "  }}").unwrap();
        writeln!(out, "}}").unwrap();
        writeln!(out).unwrap();
    }

    writeln!(out, "}} // extern \"C\"").unwrap();
    writeln!(out).unwrap();
}

